"use client";

import { ArrowRightIcon, CheckIcon } from "lucide-react";
import {
  AnimatePresence,
  animate,
  MotionConfig,
  motion,
  useInView,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from "motion/react";
import { type KeyboardEvent, useEffect, useId, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { SegmentedControl, SegmentedControlItem } from "@/components/ui/segmented-control";
import { cn } from "@/lib/utils";

export interface TallyLine {
  label: string;
  detail?: string;
  amount: number;
}

export interface TallyPeriod {
  id: string;
  label: string;
  range: string;
  caption: string;
  lines: TallyLine[];
}

export interface TallyHeroProps {
  periods: TallyPeriod[];
  defaultPeriod?: string;
  eyebrow?: string;
  description?: string;
  cta: { label: string; href: string };
  note?: string;
  statementLabel?: string;
  totalLabel?: string;
  reference?: string;
  reconciledLabel?: string;
  currency?: string;
  locale?: string;
  className?: string;
}

type Glyph = { key: string; kind: "digit" | "group" | "currency" | "literal"; char: string; place: number };

const ease = [0.23, 1, 0.32, 1] as const;
const hidden = "inset(0% 100% 0% 0%)";
const shown = "inset(0% 0% 0% 0%)";
const wheelStiffness = 340;
const strip = Array.from({ length: 11 }, (_, slot) => slot);

function useReducedMotionSafe() {
  const prefers = useReducedMotion();
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  return mounted && Boolean(prefers);
}

function toGlyphs(formatter: Intl.NumberFormat, total: number): { glyphs: Glyph[]; places: number } {
  const parts = formatter.formatToParts(total);
  const places = parts.filter((p) => p.type === "integer").reduce((n, p) => n + p.value.length, 0);
  let place = places;
  const glyphs: Glyph[] = [];
  parts.forEach((part, i) => {
    if (part.type === "integer") {
      for (const char of part.value) {
        place--;
        glyphs.push({ key: `d${place}`, kind: "digit", char, place });
      }
    } else if (part.type === "group") {
      glyphs.push({ key: `g${place}`, kind: "group", char: part.value, place });
    } else if (part.type === "currency") {
      glyphs.push({ key: place === places ? "currency" : "currency-end", kind: "currency", char: part.value, place: -1 });
    } else {
      glyphs.push({ key: `l${i}`, kind: "literal", char: part.value, place: -1 });
    }
  });
  return { glyphs, places };
}

function Wheel({ digit, from, direction, delay, reduce }: { digit: number; from: number; direction: number; delay: number; reduce: boolean }) {
  const turn = useMotionValue(from);
  const goal = useRef(from);
  const y = useTransform(turn, (t) => `${-(((t % 10) + 10) % 10) * 1.1}em`);

  useEffect(() => {
    const at = ((goal.current % 10) + 10) % 10;
    if (at !== digit) goal.current += direction < 0 ? -((at - digit + 10) % 10) : (digit - at + 10) % 10;
    if (reduce) {
      turn.jump(goal.current);
      return;
    }
    if (turn.get() === goal.current) return;
    const controls = animate(turn, goal.current, {
      type: "spring",
      stiffness: wheelStiffness,
      damping: 2 * Math.sqrt(wheelStiffness),
      delay,
    });
    return () => controls.stop();
  }, [digit, direction, delay, reduce, turn]);

  return (
    <>
      <span className="invisible block h-[1.1em]">0</span>
      <motion.span className="absolute inset-x-0 top-0 flex flex-col" style={{ y }}>
        {strip.map((slot) => (
          <span className="block h-[1.1em] text-center leading-[1.1em]" key={slot}>
            {slot % 10}
          </span>
        ))}
      </motion.span>
    </>
  );
}

function Counter({ value, total, formatter, reduce }: { value: number; total: number; formatter: Intl.NumberFormat; reduce: boolean }) {
  const { glyphs, places } = useMemo(() => toGlyphs(formatter, total), [formatter, total]);
  const padded = String(Math.round(value)).padStart(places, "0");
  const lit = value > 0 ? String(Math.round(value)).length : 0;

  const previous = useRef(value);
  const direction = Math.sign(value - previous.current);
  useEffect(() => {
    previous.current = value;
  }, [value]);

  const painted = useRef(false);
  useEffect(() => {
    painted.current = true;
  }, []);

  return (
    <span aria-hidden className="flex items-start">
      <AnimatePresence initial={false} mode="popLayout">
        {glyphs.map((glyph) => {
          const on = glyph.place < lit;
          if (glyph.kind === "currency") {
            return (
              <motion.span
                className="me-[0.06em] mt-[0.32em] font-medium text-[0.42em] text-muted-foreground leading-none tracking-normal"
                key={glyph.key}
                layout={reduce ? false : "position"}
                transition={{ type: "spring", duration: 0.4, bounce: 0 }}
              >
                {glyph.char}
              </motion.span>
            );
          }
          return (
            <motion.span
              animate={{ opacity: 1 }}
              className={cn(
                "relative inline-block h-[1.1em] leading-[1.1em] transition-colors duration-300",
                glyph.kind === "digit" &&
                  "overflow-hidden [mask-image:linear-gradient(to_bottom,transparent,black_16%,black_84%,transparent)]",
                glyph.kind === "literal" || on ? "text-foreground" : "text-foreground/15",
              )}
              exit={{ opacity: 0, transition: { duration: 0.1 } }}
              initial={{ opacity: 0 }}
              key={glyph.key}
              layout={reduce ? false : "position"}
              transition={{ type: "spring", duration: 0.4, bounce: 0 }}
            >
              {glyph.kind === "digit" ? (
                <Wheel
                  delay={Math.min(glyph.place, 6) * 0.012}
                  digit={Number(padded[padded.length - 1 - glyph.place])}
                  direction={direction}
                  from={painted.current ? 0 : Number(padded[padded.length - 1 - glyph.place])}
                  reduce={reduce}
                />
              ) : (
                glyph.char
              )}
            </motion.span>
          );
        })}
      </AnimatePresence>
    </span>
  );
}

function PeriodSwitch({ periods, value, onChange }: { periods: TallyPeriod[]; value: string; onChange: (id: string) => void }) {
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const index = Math.max(
    0,
    periods.findIndex((p) => p.id === value),
  );

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const moves: Record<string, number> = {
      ArrowRight: index + 1,
      ArrowDown: index + 1,
      ArrowLeft: index - 1,
      ArrowUp: index - 1,
      Home: 0,
      End: periods.length - 1,
    };
    if (!(event.key in moves)) return;
    event.preventDefault();
    const next = (moves[event.key] + periods.length) % periods.length;
    onChange(periods[next].id);
    refs.current[next]?.focus();
  };

  return (
    <SegmentedControl aria-label="Period" onKeyDown={onKeyDown} role="radiogroup" size="lg">
      {periods.map((period, i) => {
        const checked = i === index;
        return (
          <SegmentedControlItem
            aria-checked={checked}
            className="px-3 text-muted-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring"
            data-checked={checked ? "" : undefined}
            key={period.id}
            onClick={() => onChange(period.id)}
            ref={(el: HTMLButtonElement | null) => {
              refs.current[i] = el;
            }}
            role="radio"
            tabIndex={checked ? 0 : -1}
          >
            {period.label}
          </SegmentedControlItem>
        );
      })}
    </SegmentedControl>
  );
}

export function TallyHero({
  periods,
  defaultPeriod,
  eyebrow,
  description,
  cta,
  note,
  statementLabel = "Statement",
  totalLabel = "Total",
  reference,
  reconciledLabel = "Reconciled",
  currency = "USD",
  locale = "en-US",
  className,
}: TallyHeroProps) {
  const ref = useRef<HTMLElement>(null);
  const headingId = useId();
  const inView = useInView(ref, { once: true, amount: 0.35 });
  const reduce = useReducedMotionSafe();
  const formatter = useMemo(
    () => new Intl.NumberFormat(locale, { style: "currency", currency, maximumFractionDigits: 0, minimumFractionDigits: 0 }),
    [locale, currency],
  );

  const [periodId, setPeriodId] = useState(defaultPeriod ?? periods[0]?.id);
  const period = periods.find((p) => p.id === periodId) ?? periods[0];
  const lines = period.lines;
  const total = lines.reduce((sum, line) => sum + line.amount, 0);

  const [printed, setPrinted] = useState(0);
  const [swapped, setSwapped] = useState(false);
  const [announcement, setAnnouncement] = useState("");

  useEffect(() => {
    if (reduce) {
      setPrinted(Number.POSITIVE_INFINITY);
      return;
    }
    if (!inView) return;
    const timers: number[] = [];
    let step = 0;
    const tick = () => {
      step++;
      setPrinted((p) => Math.max(p, step));
      if (step <= lines.length) timers.push(window.setTimeout(tick, step === lines.length ? 420 : 400));
    };
    timers.push(window.setTimeout(tick, 280));
    return () => timers.forEach(window.clearTimeout);
  }, [inView, reduce, lines.length]);

  const choose = (id: string) => {
    if (id === periodId) return;
    const next = periods.find((p) => p.id === id);
    if (!next) return;
    setPeriodId(id);
    setSwapped(true);
    setPrinted(Number.POSITIVE_INFINITY);
    setAnnouncement(`${formatter.format(next.lines.reduce((s, l) => s + l.amount, 0))} ${next.caption}`);
  };

  const value = lines.slice(0, Math.min(printed, lines.length)).reduce((sum, line) => sum + line.amount, 0);
  const totalPrinted = printed > lines.length;
  const sweep = (delay: number) => (reduce ? { duration: 0 } : { duration: 0.26, ease, delay });

  return (
    <MotionConfig reducedMotion="user">
      <section
        aria-labelledby={headingId}
        className={cn("@container mx-auto w-full max-w-[1100px] px-4 py-12 sm:px-10 sm:py-14", className)}
        ref={ref}
      >
        <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-4">
          {eyebrow && <p className="font-medium font-mono text-muted-foreground text-xs uppercase tracking-widest">{eyebrow}</p>}
          {periods.length > 1 && <PeriodSwitch onChange={choose} periods={periods} value={period.id} />}
        </div>

        <h1
          className="mt-6 font-heading font-semibold text-[clamp(3rem,18cqi,12rem)] tabular-nums leading-none tracking-[-0.045em] @3xl:mt-8"
          id={headingId}
        >
          <span className="sr-only">
            {formatter.format(total)} {period.caption}
          </span>
          <Counter formatter={formatter} reduce={reduce} total={total} value={value} />
        </h1>

        <div className="relative mt-6 grid gap-8 @3xl:mt-10 @3xl:grid-cols-[minmax(0,1fr)_minmax(0,26rem)] @3xl:grid-rows-[auto_1fr] @3xl:gap-x-14 @3xl:gap-y-6">
          <AnimatePresence initial={false} mode="popLayout">
            <motion.p
              animate={{ opacity: 1 }}
              aria-hidden
              className="max-w-lg text-balance font-heading font-medium text-2xl leading-tight tracking-tight @3xl:text-[1.75rem]"
              exit={{ opacity: 0 }}
              initial={{ opacity: 0 }}
              key={period.id}
              transition={{ duration: 0.18, ease }}
            >
              {period.caption}
            </motion.p>
          </AnimatePresence>

          <div className="order-last flex flex-col items-start gap-6 @3xl:order-none @3xl:col-start-1 @3xl:row-start-2 @3xl:self-end">
            {description && <p className="max-w-md text-pretty text-base text-muted-foreground leading-relaxed">{description}</p>}
            <div className="flex flex-col items-start gap-3">
              <Button
                className="transition-[box-shadow,transform] duration-150 ease-out active:scale-[0.97] motion-reduce:active:scale-100"
                render={<a href={cta.href} />}
                size="lg"
              >
                {cta.label}
                <ArrowRightIcon />
              </Button>
              {note && <p className="max-w-sm text-pretty text-muted-foreground text-xs leading-relaxed">{note}</p>}
            </div>
          </div>

          <div className="@container rounded-2xl border bg-card font-mono text-[0.8125rem] shadow-xs/5 @3xl:col-start-2 @3xl:row-span-2 @3xl:row-start-1">
            <div className="flex items-baseline justify-between gap-4 border-b border-dashed px-4 py-3 text-muted-foreground text-xs sm:px-5">
              <span className="uppercase tracking-widest">{statementLabel}</span>
              <span className="truncate tabular-nums">{period.range}</span>
            </div>
            <dl className="px-4 py-2.5 sm:px-5">
              {lines.map((line, i) => {
                const latest = !swapped && !totalPrinted && i === printed - 1;
                return (
                  <motion.div
                    animate={{ clipPath: i < printed ? shown : hidden }}
                    className="flex items-end gap-2 py-1.5"
                    initial={{ clipPath: hidden }}
                    key={`${period.id}-${line.label}`}
                    transition={sweep(swapped ? i * 0.045 : 0)}
                  >
                    <dt className="flex min-w-0 items-baseline gap-2">
                      <span className="truncate">{line.label}</span>
                      {line.detail && <span className="hidden shrink-0 text-muted-foreground text-xs tabular-nums @sm:inline">{line.detail}</span>}
                    </dt>
                    <span
                      aria-hidden
                      className="mb-[0.3em] h-1 min-w-4 flex-1 bg-[radial-gradient(circle,currentColor_0.75px,transparent_1.1px)] bg-size-[5px_4px] bg-repeat-x text-foreground/30"
                    />
                    <dd
                      className={cn(
                        "shrink-0 tabular-nums transition-colors duration-500",
                        latest ? "text-success-foreground" : "text-foreground",
                      )}
                    >
                      {formatter.format(line.amount)}
                    </dd>
                  </motion.div>
                );
              })}
            </dl>
            <motion.div
              animate={{ clipPath: totalPrinted ? shown : hidden }}
              className="mx-4 flex items-baseline justify-between gap-4 border-foreground/70 border-t-[3px] border-double py-3 sm:mx-5"
              initial={{ clipPath: hidden }}
              key={`${period.id}-total`}
              transition={sweep(swapped ? lines.length * 0.045 + 0.04 : 0)}
            >
              <span className="font-medium">{totalLabel}</span>
              <span className="font-semibold text-base tabular-nums">{formatter.format(total)}</span>
            </motion.div>
            <div className="flex items-center justify-between gap-4 border-t border-dashed px-4 py-3 text-muted-foreground text-xs sm:px-5">
              <span className="truncate">{reference}</span>
              <motion.span
                animate={{ opacity: totalPrinted ? 1 : 0 }}
                className="inline-flex shrink-0 items-center gap-1 text-success-foreground"
                initial={false}
                transition={{ duration: reduce ? 0 : 0.2, delay: reduce || swapped ? 0 : 0.2 }}
              >
                <CheckIcon className="size-3.5" />
                {reconciledLabel}
              </motion.span>
            </div>
          </div>
        </div>
        <p aria-live="polite" className="sr-only">
          {announcement}
        </p>
      </section>
    </MotionConfig>
  );
}

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cva, type VariantProps } from "class-variance-authority";
import type * as React from "react";
import { cn } from "@/lib/utils";
import { Spinner } from "@/components/ui/spinner";

export const buttonVariants = cva(
  "relative inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-lg border font-medium text-base outline-none transition-shadow before:pointer-events-none before:absolute before:inset-0 before:rounded-[calc(var(--radius-lg)-1px)] pointer-coarse:after:absolute pointer-coarse:after:size-full pointer-coarse:after:min-h-11 pointer-coarse:after:min-w-11 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-64 data-loading:select-none data-loading:text-transparent sm:text-sm [&_svg:not([class*='opacity-'])]:opacity-80 [&_svg:not([class*='size-'])]:size-4.5 sm:[&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:-mx-0.5 [&_svg]:shrink-0",
  {
    defaultVariants: {
      size: "default",
      variant: "default",
    },
    variants: {
      size: {
        default: "h-9 px-[calc(--spacing(3)-1px)] sm:h-8",
        icon: "size-9 sm:size-8",
        "icon-lg": "size-10 sm:size-9",
        "icon-sm": "size-8 sm:size-7",
        "icon-xl":
          "size-11 sm:size-10 [&_svg:not([class*='size-'])]:size-5 sm:[&_svg:not([class*='size-'])]:size-4.5",
        "icon-xs":
          "size-7 rounded-md before:rounded-[calc(var(--radius-md)-1px)] sm:size-6 not-in-data-[slot=input-group]:[&_svg:not([class*='size-'])]:size-4 sm:not-in-data-[slot=input-group]:[&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-10 px-[calc(--spacing(3.5)-1px)] sm:h-9",
        sm: "h-8 gap-1.5 px-[calc(--spacing(2.5)-1px)] sm:h-7",
        xl: "h-11 px-[calc(--spacing(4)-1px)] text-lg sm:h-10 sm:text-base [&_svg:not([class*='size-'])]:size-5 sm:[&_svg:not([class*='size-'])]:size-4.5",
        xs: "h-7 gap-1 rounded-md px-[calc(--spacing(2)-1px)] text-sm before:rounded-[calc(var(--radius-md)-1px)] sm:h-6 sm:text-xs [&_svg:not([class*='size-'])]:size-4 sm:[&_svg:not([class*='size-'])]:size-3.5",
      },
      variant: {
        default:
          "not-disabled:inset-shadow-[0_1px_--theme(--color-white/16%)] border-primary bg-primary text-primary-foreground shadow-primary/24 shadow-xs hover:bg-primary/90 data-pressed:bg-primary/90 *:data-[slot=button-loading-indicator]:text-primary-foreground [:active,[data-pressed]]:inset-shadow-[0_1px_--theme(--color-black/8%)] [:disabled,:active,[data-pressed]]:shadow-none",
        destructive:
          "not-disabled:inset-shadow-[0_1px_--theme(--color-white/16%)] border-destructive bg-destructive text-white shadow-destructive/24 shadow-xs hover:bg-destructive/90 data-pressed:bg-destructive/90 *:data-[slot=button-loading-indicator]:text-white [:active,[data-pressed]]:inset-shadow-[0_1px_--theme(--color-black/8%)] [:disabled,:active,[data-pressed]]:shadow-none",
        "destructive-outline":
          "border-input bg-popover not-dark:bg-clip-padding text-destructive-foreground shadow-xs/5 not-disabled:not-active:not-data-pressed:before:shadow-[0_1px_--theme(--color-black/4%)] hover:border-destructive/32 hover:bg-destructive/4 data-pressed:border-destructive/32 data-pressed:bg-destructive/4 *:data-[slot=button-loading-indicator]:text-foreground dark:bg-input/32 dark:not-disabled:before:shadow-[0_-1px_--theme(--color-white/2%)] dark:not-disabled:not-active:not-data-pressed:before:shadow-[0_-1px_--theme(--color-white/6%)] [:disabled,:active,[data-pressed]]:shadow-none",
        ghost:
          "border-transparent text-foreground hover:bg-accent data-pressed:bg-accent *:data-[slot=button-loading-indicator]:text-foreground",
        link: "border-transparent text-foreground underline-offset-4 hover:underline data-pressed:underline *:data-[slot=button-loading-indicator]:text-foreground",
        outline:
          "border-input bg-popover not-dark:bg-clip-padding text-foreground shadow-xs/5 not-disabled:not-active:not-data-pressed:before:shadow-[0_1px_--theme(--color-black/4%)] hover:bg-accent/50 data-pressed:bg-accent/50 *:data-[slot=button-loading-indicator]:text-foreground dark:bg-input/32 dark:data-pressed:bg-input/64 dark:hover:bg-input/64 dark:not-disabled:before:shadow-[0_-1px_--theme(--color-white/2%)] dark:not-disabled:not-active:not-data-pressed:before:shadow-[0_-1px_--theme(--color-white/6%)] [:disabled,:active,[data-pressed]]:shadow-none",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/90 data-pressed:bg-secondary/90 *:data-[slot=button-loading-indicator]:text-secondary-foreground [:active,[data-pressed]]:bg-secondary/80",
      },
    },
  },
);

export interface ButtonProps extends useRender.ComponentProps<"button"> {
  variant?: VariantProps<typeof buttonVariants>["variant"];
  size?: VariantProps<typeof buttonVariants>["size"];
  loading?: boolean;
}

export function Button({
  className,
  variant,
  size,
  render,
  children,
  loading = false,
  disabled: disabledProp,
  ...props
}: ButtonProps): React.ReactElement {
  const isDisabled: boolean = Boolean(loading || disabledProp);
  const typeValue: React.ButtonHTMLAttributes<HTMLButtonElement>["type"] =
    render ? undefined : "button";

  const defaultProps = {
    children: (
      <>
        {children}
        {loading && (
          <Spinner
            className="pointer-events-none absolute"
            data-slot="button-loading-indicator"
          />
        )}
      </>
    ),
    className: cn(buttonVariants({ className, size, variant })),
    "aria-disabled": loading || undefined,
    "data-loading": loading ? "" : undefined,
    "data-slot": "button",
    disabled: isDisabled,
    type: typeValue,
  };

  return useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(defaultProps, props),
    render,
  });
}

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import * as React from "react";
import { cn } from "@/lib/utils";

export type SegmentedControlSize = "default" | "lg" | "sm";

export const segmentedControlItemSizeClassNames: Record<
  SegmentedControlSize,
  string
> = {
  default: "h-8.5 px-[calc(--spacing(2.5)-1px)] sm:h-7.5",
  lg: "h-9.5 px-[calc(--spacing(3)-1px)] sm:h-8.5",
  sm: "h-7.5 px-[calc(--spacing(2)-1px)] sm:h-6.5",
};

export const segmentedControlItemLayoutClassName =
  "gap-1.5 [&_svg:not([class*='opacity-'])]:opacity-80 [&_svg:not([class*='size-'])]:size-4.5 sm:[&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:-mx-0.5 [&_svg]:shrink-0";

export const segmentedControlIndicatorSurfaceClassName =
  "rounded-md bg-background shadow-sm/5 dark:bg-input";

const SegmentedControlContext: React.Context<SegmentedControlSize> =
  React.createContext<SegmentedControlSize>("default");

export function SegmentedControl({
  className,
  children,
  render,
  size = "default",
  ...props
}: useRender.ComponentProps<"div"> & {
  size?: SegmentedControlSize;
}): React.ReactElement {
  const defaultProps = {
    children: (
      <>
        {children}
        <SegmentedControlIndicator />
      </>
    ),
    className: cn(
      "relative z-0 flex w-fit items-center justify-center gap-0.5 rounded-lg bg-muted p-0.5",
      className,
    ),
    "data-size": size,
    "data-slot": "segmented-control",
  };

  const element = useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(defaultProps, props),
    render,
  });

  return (
    <SegmentedControlContext.Provider value={size}>
      {element}
    </SegmentedControlContext.Provider>
  );
}

export function SegmentedControlItem({
  className,
  render,
  size,
  ...props
}: useRender.ComponentProps<"button"> & {
  size?: SegmentedControlSize;
}): React.ReactElement {
  const contextSize = React.useContext(SegmentedControlContext);
  const resolvedSize = size ?? contextSize;

  const defaultProps = {
    className: cn(
      "relative inline-flex shrink-0 cursor-pointer select-none items-center justify-center whitespace-nowrap rounded-md border border-transparent font-medium text-base text-muted-foreground/72 outline-2 outline-transparent transition-[color,outline-color] hover:bg-transparent hover:text-muted-foreground focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-64 data-disabled:pointer-events-none data-disabled:opacity-64 sm:text-sm",
      "data-checked:bg-background data-checked:text-foreground data-checked:shadow-sm/5 dark:data-checked:bg-input",
      "aria-[current=page]:bg-background aria-[current=page]:text-foreground aria-[current=page]:shadow-sm/5 dark:aria-[current=page]:bg-input",
      "data-pressed:bg-background data-pressed:text-foreground data-pressed:shadow-sm/5 dark:data-pressed:bg-input",
      "[:has(>[data-slot=segmented-control-indicator]:not([hidden]))>&]:bg-transparent! [:has(>[data-slot=segmented-control-indicator]:not([hidden]))>&]:shadow-none!",
      segmentedControlItemLayoutClassName,
      segmentedControlItemSizeClassNames[resolvedSize],
      className,
    ),
    "data-size": resolvedSize,
    "data-slot": "segmented-control-item",
    ...(render ? {} : { type: "button" as const }),
  };

  return useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(defaultProps, props),
    render,
  });
}

const activeItemSelector =
  ':scope > [data-checked], :scope > [aria-current="page"], :scope > [data-pressed]';

const observedAttributes: string[] = [
  "data-checked",
  "aria-current",
  "data-pressed",
];

const MAX_LAYOUT_ROUNDING_ERROR = 2;

interface ActiveItemRect {
  height: number;
  left: number;
  top: number;
  width: number;
}

function isSameRect(
  a: ActiveItemRect | null,
  b: ActiveItemRect | null,
): boolean {
  return (
    a?.left === b?.left &&
    a?.top === b?.top &&
    a?.width === b?.width &&
    a?.height === b?.height
  );
}

function getCssSize(element: HTMLElement): { height: number; width: number } {
  const style = getComputedStyle(element);
  const width = Number.parseFloat(style.width) || 0;
  const height = Number.parseFloat(style.height) || 0;
  if (
    Math.round(width) !== element.offsetWidth ||
    Math.round(height) !== element.offsetHeight
  ) {
    return { height: element.offsetHeight, width: element.offsetWidth };
  }
  return { height, width };
}

function measureItem(item: HTMLElement, root: HTMLElement): ActiveItemRect {
  const { width, height } = getCssSize(item);
  const rootSize = getCssSize(root);
  const itemRect = item.getBoundingClientRect();
  const rootRect = root.getBoundingClientRect();
  const scaleX = rootSize.width > 0 ? rootRect.width / rootSize.width : 1;
  const scaleY = rootSize.height > 0 ? rootRect.height / rootSize.height : 1;

  const rectLeft =
    (itemRect.left - rootRect.left) / scaleX -
    root.clientLeft +
    root.scrollLeft;
  const rectTop =
    (itemRect.top - rootRect.top) / scaleY - root.clientTop + root.scrollTop;

  const isUndistorted =
    Math.abs(rectLeft - item.offsetLeft) <= MAX_LAYOUT_ROUNDING_ERROR &&
    Math.abs(rectTop - item.offsetTop) <= MAX_LAYOUT_ROUNDING_ERROR;

  return {
    height,
    left: isUndistorted ? rectLeft : item.offsetLeft,
    top: isUndistorted ? rectTop : item.offsetTop,
    width,
  };
}

function SegmentedControlIndicator(): React.ReactElement {
  const ref = React.useRef<HTMLSpanElement>(null);
  const [rect, setRect] = React.useState<ActiveItemRect | null>(null);

  React.useLayoutEffect(() => {
    const root = ref.current?.parentElement;
    if (!root) {
      return;
    }

    const update = (): void => {
      const item = root.querySelector<HTMLElement>(activeItemSelector);
      const next = item ? measureItem(item, root) : null;
      setRect((previous) => (isSameRect(previous, next) ? previous : next));
    };

    update();

    const resizeObserver = new ResizeObserver(update);
    const mutationObserver = new MutationObserver((records) => {
      if (records.some((record) => record.type === "childList")) {
        observeItems();
      }
      update();
    });
    const observeItems = (): void => {
      resizeObserver.disconnect();
      resizeObserver.observe(root);
      for (const child of root.children) {
        resizeObserver.observe(child);
        mutationObserver.observe(child, {
          attributeFilter: observedAttributes,
          attributes: true,
        });
      }
    };
    mutationObserver.observe(root, { childList: true });
    observeItems();

    return () => {
      resizeObserver.disconnect();
      mutationObserver.disconnect();
    };
  }, []);

  return (
    <span
      aria-hidden="true"
      className={cn(
        "pointer-events-none absolute top-0 left-0 -z-1 h-(--active-item-height) w-(--active-item-width) translate-x-(--active-item-left) translate-y-(--active-item-top) transition-[width,height,translate] duration-200 ease-in-out motion-reduce:transition-none",
        segmentedControlIndicatorSurfaceClassName,
      )}
      data-slot="segmented-control-indicator"
      hidden={!rect}
      ref={ref}
      style={
        {
          "--active-item-height": `${rect?.height ?? 0}px`,
          "--active-item-left": `${rect?.left ?? 0}px`,
          "--active-item-top": `${rect?.top ?? 0}px`,
          "--active-item-width": `${rect?.width ?? 0}px`,
        } as React.CSSProperties
      }
    />
  );
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

import { Loader2Icon } from "lucide-react";
import type React from "react";
import { cn } from "@/lib/utils";

export function Spinner({
  className,
  ...props
}: React.ComponentProps<typeof Loader2Icon>): React.ReactElement {
  return (
    <Loader2Icon
      aria-label="Loading"
      className={cn("animate-spin", className)}
      role="status"
      {...props}
    />
  );
}
